if($method==='GET'){$st=$pdo->query("SELECT o.id,o.folio,o.fecha,o.estado,o.total,o.metodo_pago,o.pago_estado,c.nombre cliente,c.correo FROM erp_ordenes o JOIN clientes c ON c.id=o.cliente_id WHERE o.origen='tienda' ORDER BY o.fecha DESC,o.id DESC LIMIT 250");json_response(['ok'=>true,'ordenes'=>$st->fetchAll()]);}
if($method==='PUT'){$d=body_json();$id=(int)($d['id']??0);$state=clean_string($d['estado']??'');if(!$id||!in_array($state,['en_revision','entregada','reembolsada'],true))json_response(['error'=>'Estado solicitado no válido.'],422);$pdo->beginTransaction();try{$st=$pdo->prepare("SELECT id,folio,cliente_id,estado,metodo_pago,total FROM erp_ordenes WHERE id=? AND origen='tienda' FOR UPDATE");$st->execute([$id]);$order=$st->fetch();if(!$order)throw new RuntimeException('Pedido no encontrado.');if($order['estado']==='reembolsada')throw new RuntimeException('El pedido ya fue reembolsado.');if($state==='reembolsada'){
 $st=$pdo->prepare('SELECT producto_id,cantidad FROM erp_orden_detalle WHERE orden_id=?');$st->execute([$id]);$items=$st->fetchAll();foreach($items as $it){$pdo->prepare('UPDATE productos SET stock_actual=stock_actual+?,actualizado_en=NOW() WHERE id=?')->execute([$it['cantidad'],$it['producto_id']]);$detail='Devolución por reembolso del pedido '.$order['folio'].'.';$pdo->prepare("INSERT INTO movimientos_inventario(producto_id,tipo,cantidad,motivo,detalle,fecha,usuario_id,orden_erp_id) VALUES(?,'entrada',?,'devolución',?,NOW(),?,?)")->execute([$it['producto_id'],$it['cantidad'],$detail,$user['id'],$id]);}
