 $pdo->prepare('UPDATE tienda_pagos SET estado=? WHERE orden_id=?')->execute([$payState,$id]);$pdo->prepare('UPDATE erp_ordenes SET pago_estado=? WHERE id=?')->execute([$payState,$id]);
