 $pdo->prepare('UPDATE erp_ordenes SET estado=?,actualizado_en=NOW() WHERE id=?')->execute([$state,$id]);$descriptions=['en_revision'=>'El pedido fue enviado a revisión por soporte.','entregada'=>'Pedido digital marcado como entregado.','reembolsada'=>'Reembolso simulado registrado y licencias devueltas al inventario SCM.'];$pdo->prepare('INSERT INTO erp_orden_historial(orden_id,estado,descripcion,usuario_id) VALUES(?,?,?,?)')->execute([$id,$state,$descriptions[$state],$user['id']]);$pdo->commit();json_response(['ok'=>true,'mensaje'=>'Estado del pedido actualizado.']);}catch(PDOException $e){if($pdo->inTransaction())$pdo->rollBack();error_log('[Upskill order management] '.$e->getMessage());json_response(['error'=>'No fue posible actualizar el pedido por un error interno.'],500);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();json_response(['error'=>$e->getMessage()],422);}}
